using LgymApi.Application.Notifications.Authorization;
using LgymApi.Domain.Entities;
using LgymApi.Domain.Enums;
using LgymApi.Domain.ValueObjects;

namespace LgymApi.Infrastructure.Repositories.Notifications;

internal sealed partial class NotificationSourceFactProvider
{
    private static NotificationSourceFacts InvitationFacts(NotificationSourceReference reference, IReadOnlyDictionary<Id<TrainerInvitation>, TrainerInvitation> invitations, bool recipientAvailable, bool senderAvailable)
        => invitations.TryGetValue(reference.SourceId.Rebind<TrainerInvitation>(), out var invitation)
            ? Facts(invitation.IsDeleted, recipientAvailable, senderAvailable, reference.RecipientRole == NotificationSourceRecipientRole.Trainee ? invitation.TraineeId == reference.RecipientId && invitation.TrainerId == reference.SenderId : invitation.TrainerId == reference.RecipientId && invitation.TraineeId == reference.SenderId, invitation.Status switch { TrainerInvitationStatus.Pending => NotificationSourceState.Pending, TrainerInvitationStatus.Accepted => NotificationSourceState.Accepted, TrainerInvitationStatus.Rejected => NotificationSourceState.Rejected, TrainerInvitationStatus.Expired or TrainerInvitationStatus.Revoked => NotificationSourceState.Expired, _ => NotificationSourceState.None }) : NotificationSourceFacts.Missing;
    private static NotificationSourceFacts ReportRequestFacts(NotificationSourceReference r, IReadOnlyDictionary<Id<ReportRequest>, ReportRequest> xs, IReadOnlySet<Id<CoachingEpisode>> e, bool a, bool s) => xs.TryGetValue(r.SourceId.Rebind<ReportRequest>(), out var x) ? Facts(x.IsDeleted, a, s, x.TraineeId == r.RecipientId && x.TrainerId == r.SenderId, ReportState(x.Status), hasActiveMatchingSourceEpisode: x.SourceCoachingEpisodeId.HasValue && e.Contains(x.SourceCoachingEpisodeId.Value)) : NotificationSourceFacts.Missing;
    private static NotificationSourceFacts RecurringReportAssignmentFacts(NotificationSourceReference r, IReadOnlyDictionary<Id<RecurringReportAssignment>, RecurringReportAssignment> xs, IReadOnlySet<Id<CoachingEpisode>> e, bool a, bool s) => xs.TryGetValue(r.SourceId.Rebind<RecurringReportAssignment>(), out var x) ? Facts(x.IsDeleted || !x.IsActive, a, s, x.TraineeId == r.RecipientId && x.TrainerId == r.SenderId, hasActiveMatchingSourceEpisode: x.SourceCoachingEpisodeId.HasValue && e.Contains(x.SourceCoachingEpisodeId.Value), scheduleRevisionMatches: r.ExpectedScheduleRevision == x.ScheduleRevision) : NotificationSourceFacts.Missing;
    private static NotificationSourceFacts ReportSubmissionFacts(NotificationSourceReference r, IReadOnlyDictionary<Id<ReportSubmission>, ReportSubmission> xs, IReadOnlyDictionary<Id<ReportRequest>, ReportRequest> rs, IReadOnlySet<Id<CoachingEpisode>> e, bool a, bool s) => !xs.TryGetValue(r.SourceId.Rebind<ReportSubmission>(), out var x) || !rs.TryGetValue(x.ReportRequestId, out var q) ? NotificationSourceFacts.Missing : Facts(x.IsDeleted || q.IsDeleted, a, s, (r.RecipientRole == NotificationSourceRecipientRole.Trainer ? q.TrainerId == r.RecipientId && q.TraineeId == r.SenderId : q.TraineeId == r.RecipientId && q.TrainerId == r.SenderId) && x.TraineeId == q.TraineeId, ReportState(q.Status), hasExpectedContent: x.TrainerFeedbackAddedAt.HasValue, hasActiveMatchingSourceEpisode: (x.SourceCoachingEpisodeId ?? q.SourceCoachingEpisodeId) is { } id && e.Contains(id));
    private static NotificationSourceFacts DietFacts(NotificationSourceReference r, IReadOnlyDictionary<Id<DietPlan>, DietPlan> xs, bool a, bool s) => xs.TryGetValue(r.SourceId.Rebind<DietPlan>(), out var x) ? Facts(x.IsDeleted, a, s, x.TraineeId == r.RecipientId && x.TrainerId == r.SenderId) : NotificationSourceFacts.Missing;
    private static NotificationSourceFacts NoteFacts(NotificationSourceReference r, IReadOnlyDictionary<Id<TraineeNote>, TraineeNote> xs, bool a, bool s) => xs.TryGetValue(r.SourceId.Rebind<TraineeNote>(), out var x) ? Facts(x.IsDeleted, a, s, x.TraineeId == r.RecipientId && x.TrainerId == r.SenderId, visibleToRecipient: x.VisibleToTrainee) : NotificationSourceFacts.Missing;
    private static NotificationSourceFacts RelationshipFacts(NotificationSourceReference r, IReadOnlyCollection<RelationshipRow> xs, bool a, bool s) => Facts(false, a, s, r.SenderId.HasValue, relationshipCurrentlyActive: xs.Any(x => x.TrainerId == r.RecipientId && x.TraineeId == r.SenderId));
    private static NotificationSourceFacts Facts(bool d, bool a, bool s, bool p, NotificationSourceState state = NotificationSourceState.None, bool visibleToRecipient = true, bool hasExpectedContent = true, bool relationshipCurrentlyActive = false, bool hasActiveMatchingSourceEpisode = false, bool scheduleRevisionMatches = true) => new(true, d, a, s, p, state, visibleToRecipient, hasExpectedContent, relationshipCurrentlyActive, hasActiveMatchingSourceEpisode, scheduleRevisionMatches);
    private static NotificationSourceState ReportState(ReportRequestStatus s) => s switch { ReportRequestStatus.Pending => NotificationSourceState.Pending, ReportRequestStatus.Submitted => NotificationSourceState.Submitted, ReportRequestStatus.Cancelled => NotificationSourceState.Cancelled, ReportRequestStatus.Expired => NotificationSourceState.Expired, ReportRequestStatus.Completed => NotificationSourceState.Completed, _ => NotificationSourceState.None };
}
